<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Rest;

use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientReadGateway;
use Civi\Lughauth\Features\Oidc\Authentication\Application\BackChannelLogoutDispatcher;
use Civi\Lughauth\Features\Oidc\Authentication\Application\SessionManager;
use Civi\Lughauth\Features\Oidc\Authentication\Application\Usecase\RevokeToken\RevokeTokenUsecase;
use Civi\Lughauth\Features\Oidc\Client\Domain\Gateway\ClientStoreGateway;
use Civi\Lughauth\Features\Oidc\Key\Domain\Gateway\TokenSigner;
use Civi\Lughauth\Features\Oidc\Session\Domain\Gateway\SessionStoreGateway;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Infrastructure\Http\Cookie;
use OpenApi\Attributes as OA;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;

class LogoutController
{
    private readonly string $base;

    public function __construct(
        private readonly Context $context,
        private readonly SessionManager $sessionManager,
        private readonly SessionStoreGateway $sessionStore,
        private readonly ClientStoreGateway $clients,
        private readonly TokenSigner $keys,
        private readonly RevokeTokenUsecase $revokeTokenUsecase,
        private readonly TrustedClientReadGateway $trustedClients,
        private readonly BackChannelLogoutDispatcher $backChannelLogout,
    ) {
        $this->base = $this->context->getBaseUrl() . '/oauth';
    }

    #[OA\Get(
        path: '/oauth/openid/{tenant}/logout',
        summary: 'RP-Initiated Logout',
        description: 'Ends the user session. Dispatches back-channel logout notifications and renders front-channel logout iframes if registered.',
        tags: ['OIDC'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
            new OA\Parameter(name: 'id_token_hint', in: 'query', required: false, schema: new OA\Schema(type: 'string')),
            new OA\Parameter(name: 'post_logout_redirect_uri', in: 'query', required: false, schema: new OA\Schema(type: 'string')),
            new OA\Parameter(name: 'client_id', in: 'query', required: false, schema: new OA\Schema(type: 'string')),
            new OA\Parameter(name: 'state', in: 'query', required: false, schema: new OA\Schema(type: 'string')),
        ],
        responses: [
            new OA\Response(response: 302, description: 'Redirect to post_logout_redirect_uri'),
            new OA\Response(response: 200, description: 'Logout page with front-channel iframes'),
            new OA\Response(response: 400, description: 'Invalid request (missing or disallowed redirect URI)'),
        ]
    )]
    public function logout(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $cookies = $request->getCookieParams();
        $query = $request->getQueryParams();

        $sessionId = $cookies['AUTH_SESSION_ID_' . strtoupper($tenant)] ?? '';

        // Load session before deletion so we can extract the user subject for back-channel
        $session = $sessionId !== '' ? $this->sessionStore->loadSession($sessionId) : null;
        $userSub = $session?->userId ?? '';
        $issuer  = $session?->issuer ?? '';

        $this->sessionManager->removeSesion($sessionId);

        $redirectUri = $query['post_logout_redirect_uri'] ?? '';
        $clientId = $query['client_id'] ?? '';

        if ($clientId === '' && isset($query['id_token_hint'])) {
            $payload = $this->keys->parseSignedPayload($tenant, $query['id_token_hint']);
            $clientId = $payload['azp'] ?? '';
            if ($userSub === '') {
                $userSub = $payload['sub'] ?? '';
            }
        }

        if ($redirectUri === '' || $clientId === '' || !$this->isAllowedRedirect($clientId, $tenant, $redirectUri)) {
            $response->getBody()->write('{"error":"invalid_request"}');
            return $response->withStatus(400)->withHeader('Content-Type', 'application/json');
        }

        // Dispatch back-channel logout notifications (best-effort, never blocks the user)
        if ($issuer === '') {
            $issuer = $this->context->getBaseUrl() . '/oauth/openid/' . $tenant;
        }
        $this->backChannelLogout->dispatch($tenant, $issuer, $userSub, $sessionId);

        // Collect front-channel URIs and render iframe page if any are registered
        $frontChannelClients = $this->trustedClients->list()->values();
        $frontChannelUris = [];
        foreach ($frontChannelClients as $client) {
            if (!$client->isEnabled()) {
                continue;
            }
            $uri = $client->getFrontChannelLogoutUri();
            if ($uri !== null && $uri !== '') {
                $frontChannelUris[] = $uri;
            }
        }

        $response = $this->clearCookies($response, $tenant);

        if ($frontChannelUris !== []) {
            return $this->renderFrontChannelLogoutPage($response, $frontChannelUris, $redirectUri, $query['state'] ?? '');
        }

        $location = $redirectUri;
        if (isset($query['state']) && $query['state'] !== '') {
            $location .= (str_contains($redirectUri, '?') ? '&' : '?') . 'state=' . urlencode($query['state']);
        }

        return $response->withStatus(302)->withHeader('Location', $location);
    }

    #[OA\Post(
        path: '/oauth/openid/{tenant}/revoke',
        summary: 'Token Revocation (RFC 7009)',
        description: 'Revokes an access or refresh token. Always returns 200 OK even if the token is unknown or already revoked.',
        tags: ['OIDC'],
        parameters: [
            new OA\Parameter(name: 'tenant', in: 'path', required: true, schema: new OA\Schema(type: 'string')),
        ],
        requestBody: new OA\RequestBody(
            required: true,
            content: new OA\MediaType(
                mediaType: 'application/x-www-form-urlencoded',
                schema: new OA\Schema(properties: [
                    new OA\Property(property: 'token', type: 'string', description: 'Token to revoke'),
                    new OA\Property(property: 'token_type_hint', type: 'string', description: 'access_token or refresh_token'),
                    new OA\Property(property: 'client_id', type: 'string'),
                    new OA\Property(property: 'client_secret', type: 'string'),
                ])
            )
        ),
        responses: [
            new OA\Response(response: 200, description: 'Token revoked (or already invalid)'),
            new OA\Response(response: 400, description: 'Missing token parameter'),
            new OA\Response(response: 401, description: 'Client authentication failed'),
        ]
    )]
    public function revoke(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $body = (array) ($request->getParsedBody() ?? []);
        $token = (string) ($body['token'] ?? '');

        if ($token === '') {
            $response->getBody()->write('{"error":"invalid_request","error_description":"missing token parameter"}');
            return $response->withStatus(400)->withHeader('Content-Type', 'application/json');
        }

        $client = $this->authenticateClient($body);
        if ($client === null) {
            $response->getBody()->write('{"error":"invalid_client","error_description":"client authentication required"}');
            return $response->withStatus(401)
                ->withHeader('Content-Type', 'application/json')
                ->withHeader('WWW-Authenticate', 'Basic realm="OAuth2 Revocation"');
        }

        // RFC 7009: always 200 OK even if token is unknown or already revoked
        $this->revokeTokenUsecase->revoke($token, $client->id, $tenant);

        return $response->withStatus(200)->withHeader('Content-Type', 'application/json');
    }

    private function renderFrontChannelLogoutPage(
        ResponseInterface $response,
        array $uris,
        string $postLogoutRedirectUri,
        string $state,
    ): ResponseInterface {
        $iframes = '';
        foreach ($uris as $uri) {
            $escaped = htmlspecialchars($uri, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
            $iframes .= "<iframe src=\"{$escaped}\" style=\"display:none\" width=\"0\" height=\"0\"></iframe>\n";
        }

        $redirectTarget = $postLogoutRedirectUri;
        if ($state !== '') {
            $sep = str_contains($postLogoutRedirectUri, '?') ? '&' : '?';
            $redirectTarget .= $sep . 'state=' . urlencode($state);
        }
        $redirectTarget = htmlspecialchars($redirectTarget, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');

        $html = <<<HTML
        <!DOCTYPE html>
        <html lang="en">
        <head><meta charset="UTF-8"><title>Logging out…</title></head>
        <body>
        {$iframes}
        <script>
        setTimeout(function () { window.location.replace("{$redirectTarget}"); }, 2000);
        </script>
        </body>
        </html>
        HTML;

        $response->getBody()->write($html);
        return $response->withStatus(200)->withHeader('Content-Type', 'text/html; charset=UTF-8');
    }

    private function clearCookies(ResponseInterface $response, string $tenant): ResponseInterface
    {
        $path = $this->base . '/openid/' . $tenant . '/';
        $authCookie = new Cookie(name: 'AUTH_SESSION_ID_' . strtoupper($tenant), path: $path);
        $preCookie = new Cookie(name: 'PRE_SESSION_ID', path: $path);
        return $preCookie->remove($authCookie->remove($response));
    }

    private function authenticateClient(array $body): mixed
    {
        // Confidential client: Basic auth
        if (isset($_SERVER['PHP_AUTH_USER'], $_SERVER['PHP_AUTH_PW'])) {
            return $this->clients->clientData($_SERVER['PHP_AUTH_USER'], $_SERVER['PHP_AUTH_PW']);
        }

        $clientId = (string) ($body['client_id'] ?? '');
        if ($clientId === '') {
            return null;
        }

        // Confidential client: client_id + client_secret in body
        $clientSecret = (string) ($body['client_secret'] ?? '');
        if ($clientSecret !== '') {
            return $this->clients->clientData($clientId, $clientSecret);
        }

        // Public client (SPA): client_id only — security relies on azp claim validation in the usecase
        return $this->clients->preValidatedClient($clientId);
    }

    private function isAllowedRedirect(string $clientId, string $tenant, string $redirectUri): bool
    {
        return $this->clients->publicClientData($clientId, $tenant, $redirectUri, '') !== null;
    }
}
